head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30800";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["isurCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil30800' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil30800: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_iRScheduleForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_sessionFill();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30800.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_confroomTpCd_onchange
 * @description slc_confroomTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_confroomTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeState(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30800.slc_confroomTpCd_onchange' }); }
};

/**
 * @method
 * @name slc_irTpCd_onchange
 * @description slc_irTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_irTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeIRTp(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30800.slc_irTpCd_onchange' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30800.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name slc_year01_onchange
 * @description slc_year01 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_year01_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.schedules1(selfVar.value)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30800.slc_year01_onchange' }); }
};

/**
 * @method
 * @name span_onclick
 * @description 「${month.name}월」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.span_onclick = async function(e){
    try {
        await scwin.schedules2('' + dma_month.get("code") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30800.span_onclick' }); }
};

/**
 * @method
 * @name grd_calendarWeekList_2_oncellclick
 * @description grd_calendarWeekList_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_calendarWeekList_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_calendarWeekList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_calendarWeekList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: goIRSupportAppl (인자 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_calendarWeekList_2.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_findSchedules
 * @description find Schedules 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_findSchedules = async function () {
    const sbmOptions = {
        id: "tx_fn_findSchedules",
        method: "post",
        action: "/issue/IRSupport.do",
        ref: "dma_findSchedulesReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchDetail
 * @description search Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_searchDetail",
        method: "post",
        action: "/issue/IRSupport.do?method=searchIRroomDetail",
        ref: "dma_searchDetailReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/issue/IRSupport.do?method=searchIRSupportInfo",
        ref: "dma_searchListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goIRSupportAppl
 * @description go IRSupport Appl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goIRSupportAppl = async function () {
    const sbmOptions = {
        id: "tx_goIRSupportAppl",
        method: "post",
        action: "/issue/IRSupport.do?method=searchIRSupportAppl",
        ref: "dma_goIRSupportApplReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_findSchedules_xhr
 * @description find Schedules xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_findSchedules_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_findSchedules_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_findSchedules_xhr", unresolved: "action:self_submit:tx_fn_findSchedules_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $c.util.getComponent('listTab').src = "/img/main/calendar_tab_1_selected.gif";
    $c.util.getComponent('calTab').src = "/img/main/calendar_tab_2.gif";
    $c.util.getComponent('dma_findSchedulesReq').set('displayDiv', "list");
    await scwin.findSchedules();
};

/**
 * @method
 * @name calendar
 * @description calendar 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calendar = async function () {
    $c.util.getComponent('listTab').src = "/img/main/calendar_tab_1.gif";
    $c.util.getComponent('calTab').src = "/img/main/calendar_tab_2_selected.gif";
    $c.util.getComponent('dma_findSchedulesReq').set('displayDiv', "calendar");
    await scwin.findSchedules();
};

/**
 * @method
 * @name schedules1
 * @description schedules1 처리
 * @param {*} year year
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules1 = async function (year) {
    await scwin.findSchedules();
};

/**
 * @method
 * @name schedules2
 * @description schedules2 처리
 * @param {*} month month
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules2 = async function (month) {
    document.all["span" + $c.util.getComponent('dma_findSchedulesReq').get('month')].className = "";
    document.all["span" + month].className = "thisMonth";
    $c.util.getComponent('dma_findSchedulesReq').set('month', month);
    await scwin.findSchedules();
};

/**
 * @method
 * @name findSchedules
 * @description find Schedules 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findSchedules = async function () {
    scwin.form_iRScheduleForm.action = "/issue/IRSupport.do";
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRSupportInfo");
    const nr = await scwin.tx_fn_findSchedules();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30801/jldfil30801.xml", { "method": "searchIRSupportInfo" });
    }
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} calndDd calndDd
 * @param {*} applNo applNo
 * @param {String} isurCd isurCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (calndDd, applNo, isurCd) {
    const loginIsurCd = $c.util.getComponent('dma_findSchedulesReq').get('loginIsurCd');
    if (loginIsurCd === isurCd) {
        $c.util.getComponent('dma_findSchedulesReq').set('applNo', applNo);
        $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRroomDetail");
        await scwin.tx_fn_searchDetail();
    } else {

    }
};

/**
 * @method
 * @name changeIRTp
 * @description change IRTp 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.changeIRTp = function (obj) {
    const irTp = obj.value;
    if (irTp != null && irTp === "1") {
        $c.util.getComponent("slc_confroomTpCd").setValue("0030");
        document.iRScheduleForm.confroomTpCd[0].selected = true;
    } else {
        if (irTp != null && irTp === "2") {
            $c.util.getComponent("slc_confroomTpCd").setValue("0030");
            document.iRScheduleForm.confroomTpCd[0].selected = true;
        }
    }
};

/**
 * @method
 * @name changeState
 * @description change State 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.changeState = function (obj) {
    const cRoom = obj.value;
    if (cRoom === "0012") {
        $c.util.getComponent("slc_irTpCd").setValue("3");
        document.iRScheduleForm.irTpCd[2].selected = true;
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRSupportInfo");
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name goIRSupportAppl
 * @description go IRSupport Appl 처리
 * @param {*} ymd ymd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goIRSupportAppl = async function (ymd) {
    $c.util.getComponent('dma_findSchedulesReq').set('calDd', ymd);
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRSupportAppl");
    await scwin.tx_goIRSupportAppl();
};
